export interface RunState {
  attempt: number
  phase: 'ready' | 'running' | 'finished'
  startedAt: number
  elapsedMs: number
  bestMs: number | null
  checkpoint: number
  collected: string[]
}

export interface RunRules {
  checkpoints: string[]
  collectibles: string[]
}

export type RunAction = { type: 'start' | 'finish' | 'restart' } |
  { type: 'checkpoint'; index: number } | { type: 'collect'; id: string }

export function freshRun(bestMs: number | null = null, attempt = 1): RunState {
  return { attempt, phase: 'ready', startedAt: 0, elapsedMs: 0, bestMs, checkpoint: 0, collected: [] }
}

export function readRun(value: unknown): RunState | null {
  if (typeof value !== 'object' || value === null) return null
  const row = value as Record<string, unknown>
  if (!['ready', 'running', 'finished'].includes(String(row.phase)) ||
    ![row.attempt, row.startedAt, row.elapsedMs, row.checkpoint].every((n) => typeof n === 'number' && Number.isFinite(n) && n >= 0) ||
    !(row.bestMs === null || (typeof row.bestMs === 'number' && Number.isFinite(row.bestMs) && row.bestMs >= 0)) ||
    !Array.isArray(row.collected) || !row.collected.every((id) => typeof id === 'string')) return null
  return {
    attempt: row.attempt as number, phase: row.phase as RunState['phase'], startedAt: row.startedAt as number,
    elapsedMs: row.elapsedMs as number, bestMs: row.bestMs as number | null, checkpoint: row.checkpoint as number,
    collected: [...row.collected] as string[]
  }
}

export function advanceRun(state: RunState, action: RunAction, now: number, rules: RunRules): { state: RunState; accepted: boolean; message: string } {
  const deny = (message = '') => ({ state, accepted: false, message })
  if (action.type === 'restart') return { state: freshRun(state.bestMs, state.attempt + 1), accepted: true, message: 'Ready for another run' }
  if (action.type === 'start') {
    if (state.phase !== 'ready') return deny()
    return { state: { ...state, phase: 'running', startedAt: now }, accepted: true, message: 'Go!' }
  }
  if (state.phase !== 'running') return deny('Cross the start first')
  if (action.type === 'checkpoint') {
    if (action.index !== state.checkpoint || action.index < 0 || action.index >= rules.checkpoints.length) return deny()
    return { state: { ...state, checkpoint: state.checkpoint + 1 }, accepted: true, message: `Checkpoint ${state.checkpoint + 1}` }
  }
  if (action.type === 'collect') {
    if (!rules.collectibles.includes(action.id) || state.collected.includes(action.id)) return deny()
    return { state: { ...state, collected: [...state.collected, action.id] }, accepted: true, message: `${state.collected.length + 1} / ${rules.collectibles.length} collected` }
  }
  if (state.checkpoint < rules.checkpoints.length) return deny('Reach every checkpoint first')
  if (state.collected.length < rules.collectibles.length) return deny('Collect every item before finishing')
  const elapsedMs = Math.max(0, now - state.startedAt)
  return {
    state: { ...state, phase: 'finished', elapsedMs, bestMs: Math.min(state.bestMs ?? Infinity, elapsedMs) },
    accepted: true, message: 'Run complete!'
  }
}

export function elapsedRun(state: RunState, now: number): number {
  return state.phase === 'running' ? Math.max(0, now - state.startedAt) : state.elapsedMs
}
